<script lang="ts">
  import Icon from '$lib/components/Icon.svelte';
  import { getAsset } from '$lib/data/marketplace';
  import { buyerReviews, pendingReviewAssets, submitReview } from '$lib/stores/buyer';
  let selected=''; let rating=5; let title=''; let text=''; let formOpen=false;
  function open(slug:string){selected=slug;rating=5;title='';text='';formOpen=true;}
  function submit(){if(selected&&title.trim()&&text.trim()){submitReview({slug:selected,rating,title:title.trim(),text:text.trim()});formOpen=false;}}
</script>
<svelte:head><title>Your reviews — AssetGuru</title></svelte:head>
<header class="page-head"><div><span class="eyebrow">Verified buyer voice</span><h1>Your <span class="gradient-text">reviews.</span></h1><p>Help other GameGuru MAX developers understand quality, compatibility and creator support.</p></div><div class="score"><Icon name="star" size={20}/><span><b>{$buyerReviews.length}</b><small>reviews published</small></span></div></header>
<section class="pending glass"><div class="panel-head"><div><span class="eyebrow">Ready for feedback</span><h2>Purchased assets awaiting a review</h2></div><span>{$pendingReviewAssets.length} remaining</span></div>{#if $pendingReviewAssets.length}<div class="pending-grid">{#each $pendingReviewAssets as item}<article><img src={item.asset.image} alt=""/><div><h3>{item.asset.title}</h3><a href={`/creators/${item.asset.creatorSlug}`}>{item.asset.creator} ✓</a><p>{item.asset.summary}</p><button class="button button-primary" type="button" onclick={()=>open(item.asset.slug)}><Icon name="star" size={16}/> Write review</button></div></article>{/each}</div>{:else}<div class="empty-inline"><Icon name="check" size={27}/><span><b>All caught up</b><small>You have reviewed every eligible purchase.</small></span></div>{/if}</section>
<section class="published glass"><div class="panel-head"><div><span class="eyebrow">Published feedback</span><h2>Your review history</h2></div></div>{#each $buyerReviews as review}{#if getAsset(review.slug)}{@const asset=getAsset(review.slug)!}<article class="review"><img src={asset.image} alt=""/><div><div class="review-head"><span><b>{asset.title}</b><small>{review.submitted} · Verified purchase</small></span><em>{'★'.repeat(review.rating)}{'☆'.repeat(5-review.rating)}</em></div><h3>{review.title}</h3><p>“{review.text}”</p><div class="review-actions"><a href={`/marketplace/${asset.slug}`}>View product</a><button type="button" onclick={()=>open(asset.slug)}>Edit review</button></div></div></article>{/if}{/each}</section>
{#if formOpen}<div class="modal-backdrop" role="presentation" onclick={(event)=>{if(event.target===event.currentTarget)formOpen=false;}}><form class="modal glass" onsubmit={(event)=>{event.preventDefault();submit();}}><button class="close" type="button" onclick={()=>formOpen=false}><Icon name="close" size={18}/></button><span class="eyebrow">Verified purchase</span><h2>{getAsset(selected)?.title}</h2><label>Rating<div class="stars">{#each [1,2,3,4,5] as star}<button type="button" class:active={star<=rating} onclick={()=>rating=star}>★</button>{/each}</div></label><label>Review title<input bind:value={title} required maxlength="80" placeholder="Sum up your experience"/></label><label>Your review<textarea bind:value={text} required minlength="40" placeholder="How was the quality, setup, compatibility and creator support?"></textarea></label><p>Reviews are attached to the purchased asset and version context. AssetGuru moderates abuse, not honest criticism.</p><button class="button button-primary" type="submit">Submit review</button></form></div>{/if}
